import React from 'react';

interface Props {
  title?: string;
}

export const Navbar: React.FC<Props> = ({ title = 'Admin Panel' }) => {
  console.log('Rendering Navbar');
  return (
    <header style={{
      height: 56,
      background: '#0b69ff',
      color: 'white',
      display: 'flex',
      alignItems: 'center',
      padding: '0 16px',
    //   boxShadow: '0 1px 0 rgba(255,255,255,0.03)'
    }}>
      <h1 style={{ fontSize: 16, margin: 0 }}>{title}</h1>
    </header>
  );
};

export default Navbar;
